#include <string>

using namespace std;

class Solution {
public:
    int maxScore(string s) {
        int ones = count(s.begin(), s.end(), '1');
        int zeros = 0, maxScore = 0;
        for (int i = 0; i < s.size() - 1; ++i) {
            zeros += s[i] == '0';
            ones -= s[i] == '1';
            maxScore = max(maxScore, zeros + ones);
        }
        return maxScore;
    }
};
